+export function flushDeferred(world: World): void {
+    const ctx = world[$internal];
+    const buffer = ctx.deferredStack[ctx.deferredStack.length - 1];
+    if (!buffer?.commands.length || ctx.isDeferredFlushing) return;
+
+    const before = snapshot(world);
+    const nullified = new Set<Entity>();
+    for (const entity of buffer.spawned) {
+        if (buffer.commands.some((command) => command.type === 'destroy' && command.entity === entity)) {
+            nullified.add(entity);
+        }
+    }
+
+    ctx.isDeferredFlushing = true;
+    try {
+        for (const command of buffer.commands) {
+            if (nullified.has(command.entity)) continue;
+            if (command.type === 'spawn') {
+                activateEntity(world, command.entity, ...command.traits);
+            } else {
+                // A destroyed source (or a relation target that was nullified) is a no-op.
+                if (!isEntityAlive(ctx.entityIndex, command.entity)) continue;
+                execute(world, command, nullified);
+            }
+        }
+        for (const entity of nullified) {
+            if (isEntityAlive(ctx.entityIndex, entity)) releaseEntity(ctx.entityIndex, entity);
+            ctx.entityTraits.delete(entity);
+        }
+    } finally {
+        buffer.commands.length = 0;
+        buffer.spawned.clear();
+        ctx.isDeferredFlushing = false;
+    }
