+function execute(world: World, command: Exclude<DeferredCommand, { type: 'spawn' }>, nullified: Set<Entity>) {
+    switch (command.type) {
+        case 'destroy':
+            if (command.entity === world[$internal].worldEntity) {
+                throw new Error('Koota: The world entity cannot be destroyed with deferred commands.');
+            }
+            destroyEntity(world, command.entity);
+            return;
+        case 'add':
+            for (const item of command.traits) {
+                if (isRelationPair(item) && typeof item[$internal].target === 'number' && nullified.has(item[$internal].target)) continue;
